export function BusyBlock({
  label = "{{label}}",
  start = "{{start}}",
  end = "{{end}}",
  date = "{{date}}",
  reason = "{{reason}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ font: "14px/1.4 system-ui, sans-serif", color: "#FAF7F2", width: 300, padding: "16px 18px", borderRadius: 10, boxSizing: "border-box", background: accent, backgroundImage: "repeating-linear-gradient(135deg, rgba(250,247,242,.08) 0 6px, transparent 6px 12px)" }}>
      <p style={{ margin: "0 0 6px", fontWeight: 700, display: "flex", alignItems: "center", gap: 8, flexWrap: "wrap" }}>
        {label} <span style={{ fontSize: 11, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", background: "rgba(250,247,242,.18)", padding: "2px 8px", borderRadius: 999 }}>{reason}</span>
      </p>
      <p style={{ margin: 0, fontVariantNumeric: "tabular-nums", opacity: .85 }}>
        <time dateTime={`${date}T${start}`}>{start}</time>&ndash;<time dateTime={`${date}T${end}`}>{end}</time>
      </p>
    </div>
  );
}
